def rrf(rankings, k=60, weights=None):
    # rankings: list of ranked lists of doc ids, best first
    weights = weights or [1.0] * len(rankings)
    score = {}
    for w, ranked in zip(weights, rankings):
        for rank, doc in enumerate(ranked, start=1):
            score[doc] = score.get(doc, 0.0) + w / (k + rank)
    return sorted(score, key=score.get, reverse=True)

bm25  = ["D4", "D3", "D6", "D1", "D8"]
dense = ["D2", "D7", "D3", "D1", "D5"]
print(rrf([bm25, dense]))
# ['D3', 'D1', 'D4', 'D2', 'D7', 'D6', 'D8', 'D5'] (ties keep insertion order)
